import{_ as o,o as t,c as r,a2 as d}from"./chunks/framework.eFe5Lsvn.js";const f=JSON.parse('{"title":"Coming from Choreo","description":"","frontmatter":{},"headers":[],"relativePath":"lib/from-choreo.md","filePath":"lib/from-choreo.md"}'),a={name:"lib/from-choreo.md"};function i(n,e,c,s,l,m){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="coming-from-choreo" tabindex="-1">Coming from Choreo <a class="header-anchor" href="#coming-from-choreo" aria-label="Permalink to &quot;Coming from Choreo&quot;">​</a></h1><p>MayhemLib&#39;s API is modeled on ChoreoLib&#39;s. The one real difference is that you don&#39;t write a controller. MayhemLib runs feedback, time dilation and bump recovery itself and hands your drivetrain field speeds plus per-module force feedforward.</p><table tabindex="0"><thead><tr><th>Choreo</th><th>MayhemLib</th></tr></thead><tbody><tr><td><code>new AutoFactory(pose, resetOdometry, controller, flip, drive)</code></td><td><code>new AutoFactory(pose, resetOdometry, fieldSpeeds, driveCommandConsumer, flip, drive)</code>, or <code>CtreSwerve.autoFactory(drivetrain)</code></td></tr><tr><td><code>routine.trajectory(&quot;name&quot;)</code>, <code>routine.trajectory(&quot;name&quot;, split)</code></td><td>Same. Loads <code>deploy/mayhem/&lt;name&gt;.mtraj</code>.</td></tr><tr><td><code>traj.atTime(&quot;event&quot;)</code></td><td>Same. Also stays true for the whole duration of a zone marker.</td></tr><tr><td><code>SwerveSample</code> + your own PID in the controller</td><td>Built in. Tune with <code>withFollowerConfig(...)</code>.</td></tr><tr><td>—</td><td><code>traj.recovering()</code>, <code>withRecoveryConfig(...)</code>, <code>withVisionBoost(...)</code>, <code>withTelemetry(true)</code></td></tr></tbody></table><h2 id="differences-to-keep-in-mind" tabindex="-1">Differences to keep in mind <a class="header-anchor" href="#differences-to-keep-in-mind" aria-label="Permalink to &quot;Differences to keep in mind&quot;">​</a></h2><ul><li><strong>No controller to write.</strong> Pass a measured-speeds supplier and a <code>DriveCommand</code> consumer instead. Tune the built-in follower under <a href="/Mayhem/lib/tuning">Tuning the follower</a>.</li><li><strong>Force feedforward.</strong> The command carries per-module wheel forces (<code>wheelForceX/Y</code>, field frame, newtons) in addition to field speeds.</li><li><strong>Bump recovery.</strong> If the robot gets knocked off the path, it takes the fastest feasible bridge back. See <a href="/Mayhem/lib/recovery">Bump recovery</a>.</li><li><strong>Module order.</strong> FL, FR, BL, BR. The robot in the Mayhem app must use the same order as your drivetrain. See <a href="/Mayhem/reference/conventions">Conventions</a>.</li></ul>',5)])])}const u=o(a,[["render",i]]);export{f as __pageData,u as default};
